style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("web.roblox.com") {
:root {
    bg-img: url("https://i.ibb.co/RTPhJvQG/Natsusaki-CUnet-noise-scale-Level1-x3-000000.png");
    overlay-color: rgba(0,0,0,0.45); /* darken background for contrast */
    panel-bg: rgba(255,255,255,0.03); /* translucent panels */
    accent: #ff7b7b; /* optional accent for highlights */
    text-light: #eaeaea;
    text-dim: #c9c9c9;
  }

  /* Base background */
  html, body {
    min-height: 100%;
    background-image: var(--bg-img) !important;
    background-repeat: no-repeat !important;
    background-position: center center !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-color: #000000 !important; /* fallback */
    color: var(--text-light) !important;
    transition: background 300ms ease, color 200ms ease;
  }

  /* Add a full-page dark overlay to improve readability */
  html::before {
    content: "";
    position: fixed;
    inset: 0;
    pointer-events: none;
    background: linear-gradient(180deg, rgba(0,0,0,0.35), rgba(0,0,0,0.6));
    mix-blend-mode: normal;
    z-index: 0;
  }

  /* Make main site containers transparent so background shows through */
  /* common container selectors; these should cover most Roblox layouts */
  #container,
  .container-main,
  .main-content,
  .site-content,
  .content,
  .page-container,
  .scroller,
  .rbx-game-details,
  .game-page-container {
    background: transparent !important;
    backdrop-filter: blur(4px) saturate(120%);
    z-index: 1;
  }

  /* Panels and cards: light translucent backgrounds to keep UI readable */
  .card,
  .card-body,
  .modal,
  .modal-dialog,
  .panel,
  .rbx-left-col,
  .rbx-right-col,
  .section-content,
  .profile-card,
  .game-card {
    background: linear-gradient(180deg, rgba(255,255,255,0.02), rgba(0,0,0,0.06)) !important;
    border: 1px solid rgba(255,255,255,0.04) !important;
    box-shadow: 0 6px 18px rgba(0,0,0,0.45) !important;
    color: var(--text-light) !important;
  }

  /* Navbar tweaks: translucent so background is visible but readable */
  header, .navbar, .top-nav, .rbx-navbar {
    background: rgba(0,0,0,0.35) !important;
    border-bottom: 1px solid rgba(255,255,255,0.03) !important;
    backdrop-filter: blur(6px) !important;
    z-index: 10;
  }

  /* Footer */
  footer, .site-footer {
    background: rgba(0,0,0,0.45) !important;
    color: var(--text-dim) !important;
  }

  /* Text and links */
  a, button, input, textarea, select, .text, .rbx-text {
    color: var(--text-light) !important;
  }
  a:hover, button:hover {
    color: white !important;
    text-decoration: none !important;
  }

  /* Buttons */
  .btn, button, .rbx-button, .btn-primary {
    background: linear-gradient(180deg, rgba(255,255,255,0.03), rgba(0,0,0,0.06)) !important;
    border: 1px solid rgba(255,255,255,0.06) !important;
    color: var(--text-light) !important;
  }

  /* Input fields */
  input[type="text"], input[type="search"], input[type="email"], textarea, .input, .form-control {
    background: rgba(255,255,255,0.02) !important;
    border: 1px solid rgba(255,255,255,0.04) !important;
    color: var(--text-light) !important;
  }

  /* Cards that use images: keep them intact */
  img, .thumbnail, .game-image, .thumbnail-2d, .avatar-headshot {
    image-rendering: auto !important;
    filter: none !important;
  }

  /* Make sure popups/modals sit above overlay */
  .modal, .modal-backdrop, .modal-dialog {
    z-index: 99999 !important;
  }

  /* Fix for text that might be too dim: boost contrast where needed */
  .text-weak, .muted, .help-text, .description {
    color: var(--text-dim) !important;
  }

  /* Optional: small accent touches (uncomment if you want colored highlights) */
  /*
  .btn-primary, .rbx-btn-primary, .badge-primary {
    background: linear-gradient(180deg, var(--accent), darken(var(--accent), 10%)) !important;
    border-color: rgba(255,255,255,0.06) !important;
  }
  */

  /* Mobile adjustments: ensure background scales nicely */
  @media (max-width: 900px) {
    html::before { background: rgba(0,0,0,0.5); }
    body { background-position: top center !important; }
  }
}
